 :root{color-scheme:dark;--ink:#f4f1e8;--muted:#a9b5b4;--lime:#d8f36a;--coral:#ff735f;--panel:#17262c}
 *{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101a20;color:var(--ink);font-family:ui-rounded,"Trebuchet MS",system-ui,sans-serif;touch-action:none}
 body{display:grid;place-items:center;background:radial-gradient(ellipse at 50% 35%,#263941 0,#101a20 72%)}
